package com.crm.customer.service;
import com.crm.security.AuthenticatedUserPrincipal;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.access.AccessDeniedException;import jakarta.validation.Validation;
public final class ContactAccess {private ContactAccess(){}private static final jakarta.validation.Validator VALIDATOR=Validation.buildDefaultValidatorFactory().getValidator();public static Authentication auth(){return SecurityContextHolder.getContext().getAuthentication();}public static long role(String... roles){var a=auth();var principal=AuthenticatedUserPrincipal.require(a);if(a.getAuthorities().stream().noneMatch(r->java.util.Arrays.asList(roles).contains(r.getAuthority())))throw new AccessDeniedException("Contact access denied");return principal.userId();}public static void valid(Object value){if(value==null||!VALIDATOR.validate(value).isEmpty())throw new IllegalArgumentException("Invalid contact input");}public static org.springframework.data.domain.PageRequest page(int page){if(page<0)throw new IllegalArgumentException("Invalid page");return org.springframework.data.domain.PageRequest.of(page,20,org.springframework.data.domain.Sort.by("id").descending());}public static org.springframework.web.server.ResponseStatusException missing(){return new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Contact resource unavailable");}public static org.springframework.web.server.ResponseStatusException conflict(){return new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"Contact state conflicts with operation");}}
